  if(!window.__onlineStoreLeaveGuardBoundV21){
    window.__onlineStoreLeaveGuardBoundV21=true;
    const nativeAdd=window.__nativeAddEventListenerOnlineV21||window.addEventListener.bind(window);
    nativeAdd("beforeunload",event=>{if(!onlineStoreRoomDirtyV16&&!window.__onlineStoreSettingsDirtyV21)return;event.preventDefault();event.returnValue="";});
  }
  setupOnlineStoreSettingsV12();
  setupOnlineStoreHistoryV14();
  setupPageJumpControlsV14();
  setupStorePreviewV13();
