/* ================================================================
   Online Store V6.7 - Stable Reference Shipping Input Controller
   - fixes V6.4 duplicate-key/input composition issue (e.g. 20 -> 2200)
   - one raw text value is authoritative while editing
   - formatting occurs only on blur
   - Line Clear suggestion never overwrites active manual typing
   - local UI only; no sync/fetch/observer/polling changes
   ================================================================ */
window.ONLINE_STORE_V62_ACTIVE=true;

function v62ShippingInput(){return document.getElementById('onlineStoreShippingCostV14');}
function v62NormalizeDigitChars(value){
  return String(value??'')
    .replace(/[０-９]/g,ch=>String(ch.charCodeAt(0)-0xFF10))
    .replace(/[．。]/g,'.')
    .replace(/[，,]/g,'')
    .replace(/\s+/g,'')
    .replace(/^RM/i,'');
}
function v62SanitizeShippingRaw(value){
  let s=v62NormalizeDigitChars(value).replace(/[^0-9.]/g,'');
  const first=s.indexOf('.');
  if(first>=0)s=s.slice(0,first+1)+s.slice(first+1).replace(/\./g,'');
  if(s.startsWith('.'))s='0'+s;
  if(first>=0||s.includes('.')){
    const p=s.indexOf('.');
    if(p>=0)s=s.slice(0,p+1)+s.slice(p+1,p+3);
  }
  return s;
}
function v62ExpectedFromBeforeInput(input,e){
  const value=String(input.value??'');
  const start=Number.isInteger(input.selectionStart)?input.selectionStart:value.length;
  const end=Number.isInteger(input.selectionEnd)?input.selectionEnd:start;
  const type=String(e.inputType||'');
  let next=value;
  if(type.startsWith('insert')){
    if(type==='insertFromPaste'||type==='insertFromDrop')return null;
    const data=v62NormalizeDigitChars(e.data??'');
    next=value.slice(0,start)+data+value.slice(end);
  }else if(type==='deleteContentBackward'){
    if(start!==end)next=value.slice(0,start)+value.slice(end);
    else if(start>0)next=value.slice(0,start-1)+value.slice(end);
  }else if(type==='deleteContentForward'){
    if(start!==end)next=value.slice(0,start)+value.slice(end);
    else next=value.slice(0,start)+value.slice(end+1);
  }else if(type.startsWith('delete')){
    next=value.slice(0,start)+value.slice(end);
  }else return null;
  return v62SanitizeShippingRaw(next);
}
function v62SetShippingRaw(input,value,caret=null){
  input.value=value;
  input.dataset.v61Editing='1';
  input.dataset.v60Manual='1';
  input.dataset.v62Raw=value;
  const badge=document.getElementById('v60ShippingModeBadge');
  if(badge){badge.textContent='手动调整';badge.classList.add('manual');}
  const reset=document.getElementById('v60RestoreShippingSuggestion');if(reset)reset.disabled=false;
  try{v42MarkEditorDirty();}catch(_){ }
  if(caret!=null){try{input.setSelectionRange(caret,caret);}catch(_){ }}
}
function v62BindShippingInput(){
  const input=v62ShippingInput();if(!input||input.dataset.v62Bound==='1')return;
  input.dataset.v62Bound='1';input.type='text';input.inputMode='decimal';input.autocomplete='off';

  input.addEventListener('beforeinput',e=>{
    if(e.isComposing)return;
    const expected=v62ExpectedFromBeforeInput(input,e);
    if(expected==null)return;
    input.dataset.v62Expected=expected;
  });

  // Runs at the target after document capture handlers. If any legacy handler has
  // rewritten the field, restore exactly what the user's keystroke meant.
  input.addEventListener('input',e=>{
    if(e.isComposing)return;
    const expected=input.dataset.v62Expected;
    const raw=expected!=null&&expected!==''?expected:v62SanitizeShippingRaw(input.value);
    const finalRaw=(expected==='')?'':raw;
    delete input.dataset.v62Expected;
    const caret=finalRaw.length;
    v62SetShippingRaw(input,finalRaw,caret);
    try{updateOnlineStoreProfitDisplaysV13();}catch(_){ }
  });

  input.addEventListener('paste',e=>{
    e.preventDefault();
    const text=v62SanitizeShippingRaw(e.clipboardData?.getData('text')||'');
    const value=String(input.value||'');
    const start=Number.isInteger(input.selectionStart)?input.selectionStart:value.length;
    const end=Number.isInteger(input.selectionEnd)?input.selectionEnd:start;
    const next=v62SanitizeShippingRaw(value.slice(0,start)+text+value.slice(end));
    v62SetShippingRaw(input,next,start+text.length);
    try{updateOnlineStoreProfitDisplaysV13();}catch(_){ }
  });

  input.addEventListener('compositionend',()=>{
    const raw=v62SanitizeShippingRaw(input.value);
    v62SetShippingRaw(input,raw,raw.length);
  });

  input.addEventListener('blur',()=>{
    input.dataset.v61Editing='0';
    const raw=v62SanitizeShippingRaw(input.value);
    if(input.dataset.v60Manual==='1'){
      if(raw==='')input.value='';
      else {const n=Number(raw);input.value=Number.isFinite(n)?formatOnlineMoneyInputV12(Math.max(0,n)):raw;}
    }
    delete input.dataset.v62Raw;delete input.dataset.v62Expected;
    try{v60ApplyShippingUi();updateOnlineStoreProfitDisplaysV13();}catch(_){ }
  });
}

