  const cfg=normalizeOnlineStoreConfigV10(String(product?.id||config?.productId||''),config||{}),stock=Math.max(0,Math.floor(Number(product?.stock)||0));
  const random=Math.max(0,Math.floor(Number(cfg.randomQty)||0));
